INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "", 1, 5, "", 1, 100101, "ヒヨリ", 4, 0, "vo_empress_100101_001", 1, "vo_empress_100101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "", 2, 5, "", 1, 100103, "ヒヨリ", 4, 0, "vo_empress_100101_002", 1, "vo_empress_100101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "", 3, 5, "", 2, 100103, "ヒヨリ", 4, 0, "vo_empress_100101_003", 1, "vo_empress_100101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "", 5, 5, "", 1, 100203, "ユイ", 4, 0, "vo_empress_100201_001", 1, "vo_empress_100201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "", 6, 5, "", 1, 100203, "ユイ", 4, 0, "vo_empress_100201_002", 1, "vo_empress_100201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "", 7, 5, "", 2, 100203, "ユイ", 4, 0, "vo_empress_100201_003", 1, "vo_empress_100201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "", 9, 5, "", 1, 100301, "レイ", 4, 0, "vo_empress_100301_001", 1, "vo_empress_100301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "", 10, 5, "", 1, 100303, "レイ", 4, 0, "vo_empress_100301_002", 1, "vo_empress_100301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "", 11, 5, "", 2, 100303, "レイ", 4, 0, "vo_empress_100301_003", 1, "vo_empress_100301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "", 13, 5, "", 1, 100401, "ミソギ", 4, 0, "vo_empress_100401_001", 1, "vo_empress_100401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "", 14, 5, "", 1, 100401, "ミソギ", 4, 0, "vo_empress_100401_002", 1, "vo_empress_100401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "", 15, 5, "", 2, 100403, "ミソギ", 4, 0, "vo_empress_100401_003", 1, "vo_empress_100401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "", 17, 5, "", 1, 100501, "マツリ", 4, 0, "vo_empress_100501_001", 1, "vo_empress_100501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "", 18, 5, "", 1, 100501, "マツリ", 4, 0, "vo_empress_100501_002", 1, "vo_empress_100501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "", 19, 5, "", 2, 100503, "マツリ", 4, 0, "vo_empress_100501_003", 1, "vo_empress_100501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "", 21, 5, "", 1, 100603, "アカリ", 4, 0, "vo_empress_100601_001", 1, "vo_empress_100601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "", 22, 5, "", 1, 100601, "アカリ", 4, 0, "vo_empress_100601_002", 1, "vo_empress_100601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "", 23, 5, "", 2, 100603, "アカリ", 4, 0, "vo_empress_100601_003", 1, "vo_empress_100601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "", 25, 5, "", 1, 100701, "ミヤコ", 4, 0, "vo_empress_100701_001", 1, "vo_empress_100701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "", 26, 5, "", 1, 100702, "ミヤコ", 4, 0, "vo_empress_100701_002", 1, "vo_empress_100701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "", 27, 5, "", 2, 100703, "ミヤコ", 4, 0, "vo_empress_100701_003", 1, "vo_empress_100701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "", 29, 5, "", 1, 100801, "ユキ", 4, 0, "vo_empress_100801_001", 1, "vo_empress_100801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "", 30, 5, "", 1, 100801, "ユキ", 4, 0, "vo_empress_100801_002", 1, "vo_empress_100801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "", 31, 5, "", 2, 100801, "ユキ", 4, 0, "vo_empress_100801_003", 1, "vo_empress_100801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "", 33, 5, "", 1, 100901, "アンナ", 4, 0, "vo_empress_100901_001", 1, "vo_empress_100901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "", 34, 5, "", 1, 100903, "アンナ", 4, 0, "vo_empress_100901_002", 1, "vo_empress_100901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "", 35, 5, "", 2, 100903, "アンナ", 4, 0, "vo_empress_100901_003", 1, "vo_empress_100901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "", 37, 5, "", 1, 101001, "マホ", 4, 0, "vo_empress_101001_001", 1, "vo_empress_101001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "", 38, 5, "", 1, 101001, "マホ", 4, 0, "vo_empress_101001_002", 1, "vo_empress_101001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "", 39, 5, "", 2, 101003, "マホ", 4, 0, "vo_empress_101001_003", 1, "vo_empress_101001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "", 41, 5, "", 1, 101101, "リノ", 4, 0, "vo_empress_101101_001", 1, "vo_empress_101101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "", 42, 5, "", 1, 101101, "リノ", 4, 0, "vo_empress_101101_002", 1, "vo_empress_101101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "", 43, 5, "", 2, 101103, "リノ", 4, 0, "vo_empress_101101_003", 1, "vo_empress_101101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "", 45, 5, "", 1, 101201, "ハツネ", 4, 0, "vo_empress_101201_001", 1, "vo_empress_101201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "", 46, 5, "", 1, 101202, "ハツネ", 4, 0, "vo_empress_101201_002", 1, "vo_empress_101201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "", 47, 5, "", 2, 101203, "ハツネ", 4, 0, "vo_empress_101201_003", 1, "vo_empress_101201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "", 49, 5, "", 1, 101301, "ナナカ", 4, 0, "vo_empress_101301_001", 1, "vo_empress_101301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "", 50, 5, "", 1, 101301, "ナナカ", 4, 0, "vo_empress_101301_002", 1, "vo_empress_101301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "", 51, 5, "", 2, 101303, "ナナカ", 4, 0, "vo_empress_101301_003", 1, "vo_empress_101301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "", 53, 5, "", 1, 101401, "カスミ", 4, 0, "vo_empress_101401_001", 1, "vo_empress_101401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "", 54, 5, "", 1, 101401, "カスミ", 4, 0, "vo_empress_101401_002", 1, "vo_empress_101401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "", 55, 5, "", 2, 101403, "カスミ", 4, 0, "vo_empress_101401_003", 1, "vo_empress_101401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "", 57, 5, "", 1, 101501, "ミサト", 4, 0, "vo_empress_101501_001", 1, "vo_empress_101501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "", 58, 5, "", 1, 101501, "ミサト", 4, 0, "vo_empress_101501_002", 1, "vo_empress_101501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "", 59, 5, "", 2, 101501, "ミサト", 4, 0, "vo_empress_101501_003", 1, "vo_empress_101501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "", 61, 5, "", 1, 101601, "スズナ", 4, 0, "vo_empress_101601_001", 1, "vo_empress_101601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "", 62, 5, "", 1, 101601, "スズナ", 4, 0, "vo_empress_101601_002", 1, "vo_empress_101601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "", 63, 5, "", 2, 101601, "スズナ", 4, 0, "vo_empress_101601_003", 1, "vo_empress_101601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "", 65, 5, "", 1, 101701, "カオリ", 4, 0, "vo_empress_101701_001", 1, "vo_empress_101701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "", 66, 5, "", 1, 101701, "カオリ", 4, 0, "vo_empress_101701_002", 1, "vo_empress_101701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "", 67, 5, "", 2, 101703, "カオリ", 4, 0, "vo_empress_101701_003", 1, "vo_empress_101701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "", 69, 5, "", 1, 101801, "イオ", 4, 0, "vo_empress_101801_001", 1, "vo_empress_101801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "", 70, 5, "", 1, 101801, "イオ", 4, 0, "vo_empress_101801_002", 1, "vo_empress_101801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "", 71, 5, "", 2, 101803, "イオ", 4, 0, "vo_empress_101801_003", 1, "vo_empress_101801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "", 73, 5, "", 1, 102003, "ミミ", 4, 0, "vo_empress_102001_001", 1, "vo_empress_102001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "", 74, 5, "", 1, 102003, "ミミ", 4, 0, "vo_empress_102001_002", 1, "vo_empress_102001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "", 75, 5, "", 2, 102003, "ミミ", 4, 0, "vo_empress_102001_003", 1, "vo_empress_102001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "", 77, 5, "", 1, 102101, "クルミ", 4, 0, "vo_empress_102101_001", 1, "vo_empress_102101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "", 78, 5, "", 1, 102101, "クルミ", 4, 0, "vo_empress_102101_002", 1, "vo_empress_102101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "", 79, 5, "", 2, 102101, "クルミ", 4, 0, "vo_empress_102101_003", 1, "vo_empress_102101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "", 81, 5, "", 1, 102201, "ヨリ", 4, 0, "vo_empress_102201_001", 1, "vo_empress_102201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "", 82, 5, "", 1, 102201, "ヨリ", 4, 0, "vo_empress_102201_002", 1, "vo_empress_102201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "", 83, 5, "", 2, 102203, "ヨリ", 4, 0, "vo_empress_102201_003", 1, "vo_empress_102201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "", 85, 5, "", 1, 102301, "アヤネ", 4, 0, "vo_empress_102301_001", 1, "vo_empress_102301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "", 86, 5, "", 1, 102303, "アヤネ", 4, 0, "vo_empress_102301_002", 1, "vo_empress_102301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "", 87, 5, "", 2, 102303, "アヤネ", 4, 0, "vo_empress_102301_003", 1, "vo_empress_102301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "", 89, 5, "", 1, 102503, "スズメ", 4, 0, "vo_empress_102501_001", 1, "vo_empress_102501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "", 90, 5, "", 1, 102503, "スズメ", 4, 0, "vo_empress_102501_002", 1, "vo_empress_102501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "", 91, 5, "", 2, 102503, "スズメ", 4, 0, "vo_empress_102501_003", 1, "vo_empress_102501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "", 93, 5, "", 1, 102603, "リン", 4, 0, "vo_empress_102601_001", 1, "vo_empress_102601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "", 94, 5, "", 1, 102603, "リン", 4, 0, "vo_empress_102601_002", 1, "vo_empress_102601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "", 95, 5, "", 2, 102603, "リン", 4, 0, "vo_empress_102601_003", 1, "vo_empress_102601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "", 97, 5, "", 1, 102701, "エリコ", 4, 0, "vo_empress_102701_001", 1, "vo_empress_102701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "", 98, 5, "", 1, 102701, "エリコ", 4, 0, "vo_empress_102701_002", 1, "vo_empress_102701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "", 99, 5, "", 2, 102703, "エリコ", 4, 0, "vo_empress_102701_003", 1, "vo_empress_102701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "", 101, 5, "", 1, 102801, "サレン", 4, 0, "vo_empress_102801_001", 1, "vo_empress_102801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 1, 102, 3, 10000, 4002, 102801, "サレン", 4, 0, "vo_empress_102801_002", 1, "vo_empress_102801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "", 103, 5, "", 2, 102803, "サレン", 4, 0, "vo_empress_102801_003", 1, "vo_empress_102801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "", 105, 5, "", 1, 102903, "ノゾミ", 4, 0, "vo_empress_102901_001", 1, "vo_empress_102901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "", 106, 5, "", 1, 102903, "ノゾミ", 4, 0, "vo_empress_102901_002", 1, "vo_empress_102901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "", 107, 5, "", 2, 102903, "ノゾミ", 4, 0, "vo_empress_102901_003", 1, "vo_empress_102901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "", 109, 5, "", 1, 103001, "ニノン", 4, 0, "vo_empress_103001_001", 1, "vo_empress_103001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "", 110, 5, "", 1, 103001, "ニノン", 4, 0, "vo_empress_103001_002", 1, "vo_empress_103001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "", 111, 5, "", 2, 103003, "ニノン", 4, 0, "vo_empress_103001_003", 1, "vo_empress_103001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "", 113, 5, "", 1, 103101, "シノブ", 4, 0, "vo_empress_103101_001", 1, "vo_empress_103101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "", 114, 5, "", 1, 103101, "シノブ", 4, 0, "vo_empress_103101_002", 1, "vo_empress_103101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "", 115, 5, "", 2, 103103, "シノブ", 4, 0, "vo_empress_103101_003", 1, "vo_empress_103101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "", 117, 5, "", 1, 103201, "アキノ", 4, 0, "vo_empress_103201_001", 1, "vo_empress_103201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "", 118, 5, "", 1, 103201, "アキノ", 4, 0, "vo_empress_103201_002", 1, "vo_empress_103201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "", 119, 5, "", 2, 103203, "アキノ", 4, 0, "vo_empress_103201_003", 1, "vo_empress_103201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "", 121, 5, "", 1, 103301, "マヒル", 4, 0, "vo_empress_103301_001", 1, "vo_empress_103301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "", 122, 5, "", 1, 103301, "マヒル", 4, 0, "vo_empress_103301_002", 1, "vo_empress_103301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "", 123, 5, "", 2, 103303, "マヒル", 4, 0, "vo_empress_103301_003", 1, "vo_empress_103301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "", 125, 5, "", 1, 103401, "ユカリ", 4, 0, "vo_empress_103401_001", 1, "vo_empress_103401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "", 126, 5, "", 1, 103401, "ユカリ", 4, 0, "vo_empress_103401_002", 1, "vo_empress_103401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "", 127, 5, "", 2, 103403, "ユカリ", 4, 0, "vo_empress_103401_003", 1, "vo_empress_103401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "", 129, 5, "", 1, 103603, "キョウカ", 4, 0, "vo_empress_103601_001", 1, "vo_empress_103601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "", 130, 5, "", 1, 103603, "キョウカ", 4, 0, "vo_empress_103601_002", 1, "vo_empress_103601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "", 131, 5, "", 2, 103601, "キョウカ", 4, 0, "vo_empress_103601_003", 1, "vo_empress_103601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "", 133, 5, "", 1, 103701, "トモ", 4, 0, "vo_empress_103701_001", 1, "vo_empress_103701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "", 134, 5, "", 1, 103701, "トモ", 4, 0, "vo_empress_103701_002", 1, "vo_empress_103701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "", 135, 5, "", 2, 103701, "トモ", 4, 0, "vo_empress_103701_003", 1, "vo_empress_103701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "", 137, 5, "", 1, 103801, "シオリ", 4, 0, "vo_empress_103801_001", 1, "vo_empress_103801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "", 138, 5, "", 1, 103801, "シオリ", 4, 0, "vo_empress_103801_002", 1, "vo_empress_103801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "", 139, 5, "", 2, 103803, "シオリ", 4, 0, "vo_empress_103801_003", 1, "vo_empress_103801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "", 141, 5, "", 1, 104001, "アオイ", 4, 0, "vo_empress_104001_001", 1, "vo_empress_104001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "", 142, 5, "", 1, 104002, "アオイ", 4, 0, "vo_empress_104001_002", 1, "vo_empress_104001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "", 143, 5, "", 2, 104003, "アオイ", 4, 0, "vo_empress_104001_003", 1, "vo_empress_104001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "", 145, 5, "", 1, 104203, "チカ", 4, 0, "vo_empress_104201_001", 1, "vo_empress_104201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "", 146, 5, "", 1, 104201, "チカ", 4, 0, "vo_empress_104201_002", 1, "vo_empress_104201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "", 147, 5, "", 2, 104203, "チカ", 4, 0, "vo_empress_104201_003", 1, "vo_empress_104201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "", 149, 5, "", 1, 104301, "マコト", 4, 0, "vo_empress_104301_001", 1, "vo_empress_104301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "", 150, 5, "", 1, 104301, "マコト", 4, 0, "vo_empress_104301_002", 1, "vo_empress_104301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "", 151, 5, "", 2, 104303, "マコト", 4, 0, "vo_empress_104301_003", 1, "vo_empress_104301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "", 153, 5, "", 1, 104401, "イリヤ", 4, 0, "vo_empress_104401_001", 1, "vo_empress_104401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "", 154, 5, "", 1, 104401, "イリヤ", 4, 0, "vo_empress_104401_002", 1, "vo_empress_104401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "", 155, 5, "", 2, 104401, "イリヤ", 4, 0, "vo_empress_104401_003", 1, "vo_empress_104401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "", 157, 5, "", 1, 104501, "クウカ", 4, 0, "vo_empress_104501_001", 1, "vo_empress_104501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "", 158, 5, "", 1, 104501, "クウカ", 4, 0, "vo_empress_104501_002", 1, "vo_empress_104501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "", 159, 5, "", 2, 104503, "クウカ", 4, 0, "vo_empress_104501_003", 1, "vo_empress_104501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "", 161, 5, "", 1, 104601, "タマキ", 4, 0, "vo_empress_104601_001", 1, "vo_empress_104601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "", 162, 5, "", 1, 104601, "タマキ", 4, 0, "vo_empress_104601_002", 1, "vo_empress_104601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "", 163, 5, "", 2, 104603, "タマキ", 4, 0, "vo_empress_104601_003", 1, "vo_empress_104601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "", 165, 5, "", 1, 104701, "ジュン", 4, 0, "vo_empress_104701_001", 1, "vo_empress_104701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "", 166, 5, "", 1, 104701, "ジュン", 4, 0, "vo_empress_104701_002", 1, "vo_empress_104701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "", 167, 5, "", 2, 104701, "ジュン", 4, 0, "vo_empress_104701_003", 1, "vo_empress_104701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "", 169, 5, "", 1, 104801, "ミフユ", 4, 0, "vo_empress_104801_001", 1, "vo_empress_104801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "", 170, 5, "", 1, 104801, "ミフユ", 4, 0, "vo_empress_104801_002", 1, "vo_empress_104801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "", 171, 5, "", 2, 104803, "ミフユ", 4, 0, "vo_empress_104801_003", 1, "vo_empress_104801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "", 173, 5, "", 1, 104902, "シズル", 4, 0, "vo_empress_104901_001", 1, "vo_empress_104901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "", 174, 5, "", 1, 104902, "シズル", 4, 0, "vo_empress_104901_002", 1, "vo_empress_104901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "", 175, 5, "", 2, 104903, "シズル", 4, 0, "vo_empress_104901_003", 1, "vo_empress_104901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "", 177, 5, "", 1, 105001, "ミサキ", 4, 0, "vo_empress_105001_001", 1, "vo_empress_105001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "", 178, 5, "", 1, 105001, "ミサキ", 4, 0, "vo_empress_105001_002", 1, "vo_empress_105001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "", 179, 5, "", 2, 105003, "ミサキ", 4, 0, "vo_empress_105001_003", 1, "vo_empress_105001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "", 181, 5, "", 1, 105101, "ミツキ", 4, 0, "vo_empress_105101_001", 1, "vo_empress_105101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "", 182, 5, "", 1, 105101, "ミツキ", 4, 0, "vo_empress_105101_002", 1, "vo_empress_105101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "", 183, 5, "", 2, 105101, "ミツキ", 4, 0, "vo_empress_105101_003", 1, "vo_empress_105101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "", 185, 5, "", 1, 105201, "リマ", 4, 0, "vo_empress_105201_001", 1, "vo_empress_105201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 1, 186, 3, 10000, 4002, 105201, "リマ", 4, 0, "vo_empress_105201_002", 1, "vo_empress_105201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "", 187, 5, "", 2, 105201, "リマ", 4, 0, "vo_empress_105201_003", 1, "vo_empress_105201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "", 189, 5, "", 1, 105303, "モニカ", 4, 0, "vo_empress_105301_001", 1, "vo_empress_105301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "", 190, 5, "", 1, 105301, "モニカ", 4, 0, "vo_empress_105301_002", 1, "vo_empress_105301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "", 191, 5, "", 2, 105301, "モニカ", 4, 0, "vo_empress_105301_003", 1, "vo_empress_105301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "", 193, 5, "", 1, 105401, "ツムギ", 4, 0, "vo_empress_105401_001", 1, "vo_empress_105401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 1, 194, 3, 10000, 4002, 105403, "ツムギ", 4, 0, "vo_empress_105401_002", 1, "vo_empress_105401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "", 195, 5, "", 2, 105403, "ツムギ", 4, 0, "vo_empress_105401_003", 1, "vo_empress_105401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "", 197, 5, "", 1, 105503, "アユミ", 4, 0, "vo_empress_105501_001", 1, "vo_empress_105501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "", 198, 5, "", 1, 105501, "アユミ", 4, 0, "vo_empress_105501_002", 1, "vo_empress_105501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "", 199, 5, "", 2, 105503, "アユミ", 4, 0, "vo_empress_105501_003", 1, "vo_empress_105501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "", 201, 5, "", 1, 105601, "ルカ", 4, 0, "vo_empress_105601_001", 1, "vo_empress_105601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "", 202, 5, "", 1, 105601, "ルカ", 4, 0, "vo_empress_105601_002", 1, "vo_empress_105601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "", 203, 5, "", 2, 105603, "ルカ", 4, 0, "vo_empress_105601_003", 1, "vo_empress_105601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "", 205, 5, "", 1, 105803, "ペコリーヌ", 4, 0, "vo_empress_105801_001", 1, "vo_empress_105801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 1, 206, 3, 10000, 4003, 105801, "ペコリーヌ", 4, 0, "vo_empress_105801_002", 1, "vo_empress_105801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "", 207, 5, "", 2, 105803, "ペコリーヌ", 4, 0, "vo_empress_105801_003", 1, "vo_empress_105801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "", 209, 5, "", 1, 105903, "コッコロ", 4, 0, "vo_empress_105901_001", 1, "vo_empress_105901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "", 210, 5, "", 1, 105905, "コッコロ", 4, 0, "vo_empress_105901_002", 1, "vo_empress_105901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "", 211, 5, "", 2, 105903, "コッコロ", 4, 0, "vo_empress_105901_003", 1, "vo_empress_105901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 1, 213, 3, 10000, 4005, 106001, "キャル", 4, 0, "vo_empress_106001_001", 1, "vo_empress_106001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "", 214, 5, "", 1, 106003, "キャル", 4, 0, "vo_empress_106001_002", 1, "vo_empress_106001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "", 215, 5, "", 2, 106003, "キャル", 4, 0, "vo_empress_106001_003", 1, "vo_empress_106001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "", 217, 5, "", 1, 106102, "ノウェム", 4, 0, "vo_empress_106101_001", 1, "vo_empress_106101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "", 218, 5, "", 1, 106101, "ノウェム", 4, 0, "vo_empress_106101_002", 1, "vo_empress_106101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "", 219, 5, "", 2, 106103, "ノウェム", 4, 0, "vo_empress_106101_003", 1, "vo_empress_106101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "", 221, 5, "", 1, 106401, "シェフィ", 4, 0, "vo_empress_106401_001", 1, "vo_empress_106401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 1, 222, 3, 10000, 4004, 106403, "シェフィ", 4, 0, "vo_empress_106401_002", 1, "vo_empress_106401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "", 223, 5, "", 2, 106401, "シェフィ", 4, 0, "vo_empress_106401_003", 1, "vo_empress_106401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "", 225, 5, "", 1, 106501, "カヤ", 4, 0, "vo_empress_106501_001", 1, "vo_empress_106501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "", 226, 5, "", 1, 106501, "カヤ", 4, 0, "vo_empress_106501_002", 1, "vo_empress_106501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "", 227, 5, "", 2, 106503, "カヤ", 4, 0, "vo_empress_106501_003", 1, "vo_empress_106501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "", 229, 5, "", 1, 106603, "イノリ", 4, 0, "vo_empress_106601_001", 1, "vo_empress_106601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "", 230, 5, "", 1, 106601, "イノリ", 4, 0, "vo_empress_106601_002", 1, "vo_empress_106601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "", 231, 5, "", 2, 106603, "イノリ", 4, 0, "vo_empress_106601_003", 1, "vo_empress_106601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "", 233, 5, "", 1, 106701, "ホマレ", 4, 0, "vo_empress_106701_001", 1, "vo_empress_106701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "", 234, 5, "", 1, 106701, "ホマレ", 4, 0, "vo_empress_106701_002", 1, "vo_empress_106701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "", 235, 5, "", 2, 106703, "ホマレ", 4, 0, "vo_empress_106701_003", 1, "vo_empress_106701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "", 237, 5, "", 1, 106802, "ラビリスタ", 4, 0, "vo_empress_106801_001", 1, "vo_empress_106801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 1, 238, 3, 10000, 4005, 106801, "ラビリスタ", 4, 0, "vo_empress_106801_002", 1, "vo_empress_106801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "", 239, 5, "", 2, 106801, "ラビリスタ", 4, 0, "vo_empress_106801_003", 1, "vo_empress_106801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 1, 241, 3, 10000, 4005, 107001, "ネネカ", 4, 0, "vo_empress_107001_001", 1, "vo_empress_107001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "", 242, 5, "", 1, 107001, "ネネカ", 4, 0, "vo_empress_107001_002", 1, "vo_empress_107001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "", 243, 5, "", 2, 107001, "ネネカ", 4, 0, "vo_empress_107001_003", 1, "vo_empress_107001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "", 245, 5, "", 1, 107101, "クリスティーナ", 4, 0, "vo_empress_107101_001", 1, "vo_empress_107101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 1, 246, 3, 10000, 4005, 107101, "クリスティーナ", 4, 0, "vo_empress_107101_002", 1, "vo_empress_107101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "", 247, 5, "", 2, 107103, "クリスティーナ", 4, 0, "vo_empress_107101_003", 1, "vo_empress_107101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "", 249, 5, "", 1, 110801, "クロエ", 4, 0, "vo_empress_110801_001", 1, "vo_empress_110801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 1, 250, 3, 10000, 4005, 110801, "クロエ", 4, 0, "vo_empress_110801_002", 1, "vo_empress_110801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "", 251, 5, "", 2, 110803, "クロエ", 4, 0, "vo_empress_110801_003", 1, "vo_empress_110801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "", 253, 5, "", 1, 110901, "チエル", 4, 0, "vo_empress_110901_001", 1, "vo_empress_110901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "", 254, 5, "", 1, 110901, "チエル", 4, 0, "vo_empress_110901_002", 1, "vo_empress_110901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "", 255, 5, "", 2, 110903, "チエル", 4, 0, "vo_empress_110901_003", 1, "vo_empress_110901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "", 257, 5, "", 1, 111001, "ユニ", 4, 0, "vo_empress_111001_001", 1, "vo_empress_111001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "", 258, 5, "", 1, 111001, "ユニ", 4, 0, "vo_empress_111001_002", 1, "vo_empress_111001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "", 259, 5, "", 2, 111003, "ユニ", 4, 0, "vo_empress_111001_003", 1, "vo_empress_111001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "", 261, 5, "", 1, 118001, "クレジッタ", 4, 0, "vo_empress_118001_001", 1, "vo_empress_118001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "", 262, 5, "", 1, 118003, "クレジッタ", 4, 0, "vo_empress_118001_002", 1, "vo_empress_118001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "", 263, 5, "", 2, 118003, "クレジッタ", 4, 0, "vo_empress_118001_003", 1, "vo_empress_118001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "", 265, 5, "", 1, 118101, "ランファ", 4, 0, "vo_empress_118101_001", 1, "vo_empress_118101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "", 266, 5, "", 1, 118101, "ランファ", 4, 0, "vo_empress_118101_002", 1, "vo_empress_118101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "", 267, 5, "", 2, 118103, "ランファ", 4, 0, "vo_empress_118101_003", 1, "vo_empress_118101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 1, 269, 3, 10000, 4005, 118201, "ミソラ", 4, 0, "vo_empress_118201_001", 1, "vo_empress_118201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "", 270, 5, "", 1, 118201, "ミソラ", 4, 0, "vo_empress_118201_002", 1, "vo_empress_118201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "", 271, 5, "", 2, 118202, "ミソラ", 4, 0, "vo_empress_118201_003", 1, "vo_empress_118201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "", 273, 5, "", 1, 118501, "カリン", 4, 0, "vo_empress_118501_001", 1, "vo_empress_118501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "", 274, 5, "", 1, 118502, "カリン", 4, 0, "vo_empress_118501_002", 1, "vo_empress_118501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "", 275, 5, "", 2, 118503, "カリン", 4, 0, "vo_empress_118501_003", 1, "vo_empress_118501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "", 277, 5, "", 1, 118601, "ネビア", 4, 0, "vo_empress_118601_001", 1, "vo_empress_118601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "", 278, 5, "", 1, 118601, "ネビア", 4, 0, "vo_empress_118601_002", 1, "vo_empress_118601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "", 279, 5, "", 2, 118603, "ネビア", 4, 0, "vo_empress_118601_003", 1, "vo_empress_118601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "", 281, 5, "", 1, 122303, "ヴァンピィ", 4, 0, "vo_empress_122301_001", 1, "vo_empress_122301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "", 282, 5, "", 1, 122302, "ヴァンピィ", 4, 0, "vo_empress_122301_002", 1, "vo_empress_122301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "", 283, 5, "", 2, 122303, "ヴァンピィ", 4, 0, "vo_empress_122301_003", 1, "vo_empress_122301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "", 285, 5, "", 1, 123002, "アメス", 4, 0, "vo_empress_123001_001", 1, "vo_empress_123001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "", 286, 5, "", 1, 123001, "アメス", 4, 0, "vo_empress_123001_002", 1, "vo_empress_123001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "", 287, 5, "", 2, 123003, "アメス", 4, 0, "vo_empress_123001_003", 1, "vo_empress_123001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "", 289, 5, "", 1, 123301, "ネア", 4, 0, "vo_empress_123301_001", 1, "vo_empress_123301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "", 290, 5, "", 1, 123301, "ネア", 4, 0, "vo_empress_123301_002", 1, "vo_empress_123301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "", 291, 5, "", 2, 123303, "ネア", 4, 0, "vo_empress_123301_003", 1, "vo_empress_123301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "", 293, 5, "", 1, 126401, "クローチェ", 4, 0, "vo_empress_126401_001", 1, "vo_empress_126401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "", 294, 5, "", 1, 126401, "クローチェ", 4, 0, "vo_empress_126401_002", 1, "vo_empress_126401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "", 295, 5, "", 2, 126403, "クローチェ", 4, 0, "vo_empress_126401_003", 1, "vo_empress_126401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "", 297, 5, "", 1, 126501, "ライラエル", 4, 0, "vo_empress_126501_001", 1, "vo_empress_126501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 1, 298, 3, 10000, 4002, 126506, "ライラエル", 4, 0, "vo_empress_126501_002", 1, "vo_empress_126501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "", 299, 5, "", 2, 126503, "ライラエル", 4, 0, "vo_empress_126501_003", 1, "vo_empress_126501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 1, 301, 3, 10000, 4002, 127701, "リンド", 4, 0, "vo_empress_127701_001", 1, "vo_empress_127701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "", 302, 5, "", 1, 127701, "リンド", 4, 0, "vo_empress_127701_002", 1, "vo_empress_127701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "", 303, 5, "", 2, 127703, "リンド", 4, 0, "vo_empress_127701_003", 1, "vo_empress_127701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "", 305, 5, "", 1, 127801, "ヴルム", 4, 0, "vo_empress_127801_001", 1, "vo_empress_127801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 1, 306, 3, 10000, 4002, 127801, "ヴルム", 4, 0, "vo_empress_127801_002", 1, "vo_empress_127801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "", 307, 5, "", 2, 127803, "ヴルム", 4, 0, "vo_empress_127801_003", 1, "vo_empress_127801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 1, 309, 3, 10000, 4005, 129001, "エリス", 4, 0, "vo_empress_129001_001", 1, "vo_empress_129001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "", 310, 5, "", 1, 129001, "エリス", 4, 0, "vo_empress_129001_002", 1, "vo_empress_129001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "", 311, 5, "", 2, 129003, "エリス", 4, 0, "vo_empress_129001_003", 1, "vo_empress_129001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "", 313, 5, "", 1, 129601, "アネモネ", 4, 0, "vo_empress_129601_001", 1, "vo_empress_129601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "", 314, 5, "", 1, 129601, "アネモネ", 4, 0, "vo_empress_129601_002", 1, "vo_empress_129601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "", 315, 5, "", 2, 129603, "アネモネ", 4, 0, "vo_empress_129601_003", 1, "vo_empress_129601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "", 317, 5, "", 1, 129701, "ネフィ＝ネラ", 4, 0, "vo_empress_129701_001", 1, "vo_empress_129701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "", 318, 5, "", 1, 129701, "ネフィ＝ネラ", 4, 0, "vo_empress_129701_002", 1, "vo_empress_129701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "", 319, 5, "", 2, 129703, "ネフィ＝ネラ", 4, 0, "vo_empress_129701_003", 1, "vo_empress_129701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 1, 321, 3, 10000, 4003, 130001, "ヤマト", 4, 0, "vo_empress_130001_001", 1, "vo_empress_130001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "", 322, 5, "", 1, 130001, "ヤマト", 4, 0, "vo_empress_130001_002", 1, "vo_empress_130001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "", 323, 5, "", 2, 130003, "ヤマト", 4, 0, "vo_empress_130001_003", 1, "vo_empress_130001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "", 325, 5, "", 1, 130101, "ワカナ", 4, 0, "vo_empress_130101_001", 1, "vo_empress_130101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "", 326, 5, "", 1, 130101, "ワカナ", 4, 0, "vo_empress_130101_002", 1, "vo_empress_130101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "", 327, 5, "", 2, 130103, "ワカナ", 4, 0, "vo_empress_130101_003", 1, "vo_empress_130101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "", 329, 5, "", 1, 130201, "フブキ", 4, 0, "vo_empress_130201_001", 1, "vo_empress_130201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "", 330, 5, "", 1, 130201, "フブキ", 4, 0, "vo_empress_130201_002", 1, "vo_empress_130201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "", 331, 5, "", 2, 130203, "フブキ", 4, 0, "vo_empress_130201_003", 1, "vo_empress_130201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "", 333, 5, "", 1, 130901, "クルル", 4, 0, "vo_empress_130901_001", 1, "vo_empress_130901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "", 334, 5, "", 1, 130901, "クルル", 4, 0, "vo_empress_130901_002", 1, "vo_empress_130901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "", 335, 5, "", 2, 130903, "クルル", 4, 0, "vo_empress_130901_003", 1, "vo_empress_130901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "", 337, 5, "", 1, 132301, "ルイズマリー", 4, 0, "vo_empress_132301_001", 1, "vo_empress_132301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "", 338, 5, "", 1, 132301, "ルイズマリー", 4, 0, "vo_empress_132301_002", 1, "vo_empress_132301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "", 339, 5, "", 2, 132303, "ルイズマリー", 4, 0, "vo_empress_132301_003", 1, "vo_empress_132301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "", 341, 5, "", 1, 132401, "イロハ", 4, 0, "vo_empress_132401_001", 1, "vo_empress_132401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "", 342, 5, "", 1, 132401, "イロハ", 4, 0, "vo_empress_132401_002", 1, "vo_empress_132401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "", 343, 5, "", 2, 132401, "イロハ", 4, 0, "vo_empress_132401_003", 1, "vo_empress_132401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "", 345, 5, "", 1, 132501, "ソノ", 4, 0, "vo_empress_132501_001", 1, "vo_empress_132501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "", 346, 5, "", 1, 132501, "ソノ", 4, 0, "vo_empress_132501_002", 1, "vo_empress_132501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "", 347, 5, "", 2, 132503, "ソノ", 4, 0, "vo_empress_132501_003", 1, "vo_empress_132501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "", 349, 5, "", 1, 133001, "グレイス", 4, 0, "vo_empress_133001_001", 1, "vo_empress_133001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 1, 350, 3, 10000, 4001, 133003, "グレイス", 4, 0, "vo_empress_133001_002", 1, "vo_empress_133001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "", 351, 5, "", 2, 133003, "グレイス", 4, 0, "vo_empress_133001_003", 1, "vo_empress_133001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "", 353, 5, "", 1, 133101, "ヴァイオレット", 4, 0, "vo_empress_133101_001", 1, "vo_empress_133101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 1, 354, 3, 10000, 4001, 133101, "ヴァイオレット", 4, 0, "vo_empress_133101_002", 1, "vo_empress_133101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "", 355, 5, "", 2, 133103, "ヴァイオレット", 4, 0, "vo_empress_133101_003", 1, "vo_empress_133101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "", 357, 5, "", 1, 133601, "メドゥーサ", 4, 0, "vo_empress_133601_001", 1, "vo_empress_133601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "", 358, 5, "", 1, 133601, "メドゥーサ", 4, 0, "vo_empress_133601_002", 1, "vo_empress_133601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "", 359, 5, "", 2, 133603, "メドゥーサ", 4, 0, "vo_empress_133601_003", 1, "vo_empress_133601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "", 361, 5, "", 1, 134701, "ホウオウ", 4, 0, "vo_empress_134701_001", 1, "vo_empress_134701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "", 362, 5, "", 1, 134701, "ホウオウ", 4, 0, "vo_empress_134701_002", 1, "vo_empress_134701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "", 363, 5, "", 2, 134703, "ホウオウ", 4, 0, "vo_empress_134701_003", 1, "vo_empress_134701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "", 365, 5, "", 1, 134901, "カノン", 4, 0, "vo_empress_134901_001", 1, "vo_empress_134901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "", 366, 5, "", 1, 134901, "カノン", 4, 0, "vo_empress_134901_002", 1, "vo_empress_134901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "", 367, 5, "", 2, 134903, "カノン", 4, 0, "vo_empress_134901_003", 1, "vo_empress_134901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "", 369, 5, "", 1, 135501, "アイラ", 4, 0, "vo_empress_135501_001", 1, "vo_empress_135501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 1, 370, 3, 10000, 4005, 135501, "アイラ", 4, 0, "vo_empress_135501_002", 1, "vo_empress_135501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "", 371, 5, "", 2, 135503, "アイラ", 4, 0, "vo_empress_135501_003", 1, "vo_empress_135501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "", 373, 5, "", 1, 135601, "シナツ", 4, 0, "vo_empress_135601_001", 1, "vo_empress_135601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "", 374, 5, "", 1, 135601, "シナツ", 4, 0, "vo_empress_135601_002", 1, "vo_empress_135601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "", 375, 5, "", 2, 135603, "シナツ", 4, 0, "vo_empress_135601_003", 1, "vo_empress_135601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 1, 377, 3, 10000, 4001, 135801, "ユキノ", 4, 0, "vo_empress_135801_001", 1, "vo_empress_135801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "", 378, 5, "", 1, 135801, "ユキノ", 4, 0, "vo_empress_135801_002", 1, "vo_empress_135801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "", 379, 5, "", 2, 135803, "ユキノ", 4, 0, "vo_empress_135801_003", 1, "vo_empress_135801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 1, 381, 3, 10000, 4001, 135903, "サツキ", 4, 0, "vo_empress_135901_001", 1, "vo_empress_135901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "", 382, 5, "", 1, 135901, "サツキ", 4, 0, "vo_empress_135901_002", 1, "vo_empress_135901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "", 383, 5, "", 2, 135901, "サツキ", 4, 0, "vo_empress_135901_003", 1, "vo_empress_135901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "", 385, 5, "", 1, 136001, "アラクネ", 4, 0, "vo_empress_136001_001", 1, "vo_empress_136001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 1, 386, 3, 10000, 4003, 136001, "アラクネ", 4, 0, "vo_empress_136001_002", 1, "vo_empress_136001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "", 387, 5, "", 2, 136003, "アラクネ", 4, 0, "vo_empress_136001_003", 1, "vo_empress_136001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "", 389, 5, "", 1, 136201, "ナーナ", 4, 0, "vo_empress_136201_001", 1, "vo_empress_136201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "", 390, 5, "", 1, 136201, "ナーナ", 4, 0, "vo_empress_136201_002", 1, "vo_empress_136201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "", 391, 5, "", 2, 136201, "ナーナ", 4, 0, "vo_empress_136201_003", 1, "vo_empress_136201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 1, 393, 3, 10000, 4001, 136903, "ルルィ", 4, 0, "vo_empress_136901_001", 1, "vo_empress_136901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "", 394, 5, "", 1, 136901, "ルルィ", 4, 0, "vo_empress_136901_002", 1, "vo_empress_136901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "", 395, 5, "", 2, 136903, "ルルィ", 4, 0, "vo_empress_136901_003", 1, "vo_empress_136901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "", 397, 5, "", 1, 139501, "リリ", 4, 0, "vo_empress_139501_001", 1, "vo_empress_139501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 1, 398, 3, 10000, 4002, 139503, "リリ", 4, 0, "vo_empress_139501_002", 1, "vo_empress_139501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "", 399, 5, "", 2, 139503, "リリ", 4, 0, "vo_empress_139501_003", 1, "vo_empress_139501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "", 401, 5, "", 1, 139603, "クリア", 4, 0, "vo_empress_139601_001", 1, "vo_empress_139601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 1, 402, 3, 10000, 4002, 139603, "クリア", 4, 0, "vo_empress_139601_002", 1, "vo_empress_139601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "", 403, 5, "", 2, 139603, "クリア", 4, 0, "vo_empress_139601_003", 1, "vo_empress_139601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "", 405, 5, "", 1, 139701, "プレシア", 4, 0, "vo_empress_139701_001", 1, "vo_empress_139701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "", 406, 5, "", 1, 139701, "プレシア", 4, 0, "vo_empress_139701_002", 1, "vo_empress_139701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "", 407, 5, "", 2, 139703, "プレシア", 4, 0, "vo_empress_139701_003", 1, "vo_empress_139701_003");
